import{z as o,x as s,o as e,c as d,q as B,j as i,D as a,d as n,s as t,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"流动性的资产定价深化","description":"","frontmatter":{"title":"流动性的资产定价深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/apt-liquidity-deep.md","filePath":"econ/apt-liquidity-deep.md","lastUpdated":1791413859000}'),l={name:"econ/apt-liquidity-deep.md"};function p(m,E,c,h,u,D){const A=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=B('<h1 id="流动性的资产定价深化" tabindex="-1">流动性的资产定价深化 <a class="header-anchor" href="#流动性的资产定价深化" aria-label="Permalink to &quot;流动性的资产定价深化&quot;">​</a></h1><div class="epigraph"><p>资产不因难卖而不同，但买它的人会要求两笔补偿：为「这件资产难卖」付一次价，再为「大家一起难卖」付一次价。</p><footer>—— 据 Amihud and Mendelson, *Journal of Financial Economics* 1986；Acharya and Pedersen, *JFE* 2005；Brunnermeier and Pedersen, *RFS* 2009 整理</footer></div><p><a href="/econ/apt-heterogeneous-beliefs">上一课</a>说明价格由边际买者写；本课把「写价格的成本」记进收益。微观侧的地基已经打好：<a href="/econ/asymmetric-info-liquidity">不对称信息与流动性理论</a>拆过价差的构成，<a href="/econ/market-funding-liquidity">市场与融资流动性</a>拆过两种流动性的联动。缺口是定价含义：交易要过价差、冲击成本与资金约束，这些摩擦以什么形式、多大的量，进入预期收益。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>交易无成本时，横截面收益只该由协方差决定；现实里摩擦直接改写持有者的实现收益，缺口有两层。水平层：持有一只难卖的资产，实现收益被价差与冲击吃掉一块，要求收益必须抬高才打平——这是「为流动性付费」。风险层：流动性不是各资产独立的噪声，它有共同成分，且在危机中与收益同时恶化；持有「市场流动性变坏时收益也变坏」的资产，承担了一种新的状态暴露。只看水平不看风险，溢价会被记成常数；只看风险不看水平，会把价差补偿误认为超额收益。</p><p><span class="marginnote">易错点在水平效应的摊薄：Constantinides 1986 证明，比例交易成本即便不小，对要求收益的影响也远小于线性直觉——投资者会把调仓频率降下来摊薄成本；Longstaff 1995 算出的约三成折价是「完全不可交易」的上限，现实的可交易性折价远低于它。把上限当典型值，是流动性溢价文献最常见的夸大来源。</span></p><p><span class="marginnote">术语翻译：「买卖价差」是同一时刻买价与卖价之间的缺口，一买一卖立刻亏掉这一截；「冲击成本」是你的大单自己把价格推向不利方向的部分。两者都不是谁赚走的暴利，而是进出场必须付的「过路费」——所谓流动性好，就是过路费低。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两条通道各有一套度量与一组价格。水平通道：Amihud–Mendelson 1986 在纽约证交所数据上发现价差与净收益正相关——买宽价差资产的人必须预期更高的毛收益，净收益才打平；持有期机制自动摊薄，见<a href="/econ/transaction-cost-portfolio-theory">交易成本下的组合</a>。风险通道：Amihud 2002 的非流动性比把「单位成交额的价格移动」变成可算的时序（<a href="/quant/amihud-illiquidity">Amihud 非流动性</a>），Pastor–Stambaugh 2003 发现流动性冲击的系统成分有价格；Acharya–Pedersen 2005 的 LCAPM 把两通道统一成四个贝塔：资产收益对市场的贝塔、资产收益对市场流动性的贝塔、资产流动性对市场收益的贝塔、资产流动性对市场流动性的贝塔，各配各的价格。结构性来源在<a href="/econ/asymmetric-info-liquidity">不对称信息与流动性理论</a>：逆向选择成分由知情交易决定，本身随波动与信息环境移动。</p>',9)),(e(),i(r,null,{default:a(()=>[t(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20COST%5B%22%E4%BA%A4%E6%98%93%E6%91%A9%E6%93%A6%3A%20%E4%BB%B7%E5%B7%AE%20%2F%20%E5%86%B2%E5%87%BB%20%2F%20%E8%B5%84%E9%87%91%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20LVL%5B%22%E6%B0%B4%E5%B9%B3%E9%80%9A%E9%81%93%3A%20%E6%8C%81%E6%9C%89%E8%A1%A5%E5%81%BF%2C%20%E6%91%8A%E8%96%84%E5%90%8E%E6%9C%89%E9%99%90%22%5D%0A%20%20COST%20--%3E%20RISK%5B%22%E9%A3%8E%E9%99%A9%E9%80%9A%E9%81%93%3A%20%E6%B5%81%E5%8A%A8%E6%80%A7%E5%85%B1%E5%90%8C%E5%86%B2%E5%87%BB%22%5D%0A%20%20RISK%20--%3E%20LCAPM%5B%22LCAPM%3A%20%E5%9B%9B%E4%B8%AA%E8%B4%9D%E5%A1%94%E5%90%84%E9%85%8D%E4%B8%80%E4%B8%AA%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20FUND%5B%22%E8%B5%84%E9%87%91%E7%BA%A6%E6%9D%9F%E6%94%B6%E7%B4%A7%22%5D%20--%3E%20SPIRAL%5B%22%E5%87%8F%E4%BB%93%20-%20%E6%B5%81%E5%8A%A8%E6%80%A7%20-%20%E4%BB%B7%E6%A0%BC%E7%9A%84%E8%9E%BA%E6%97%8B%22%5D%0A%20%20SPIRAL%20--%3E%20TV%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E6%BA%A2%E4%BB%B7%E6%97%B6%E5%8F%98%2C%20%E5%8D%B1%E6%9C%BA%E4%B8%AD%E6%94%BE%E5%A4%A7%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两条通道的枢纽都是边际持有者的资产负债表。常态下，边际者是低约束的长期投资者，水平溢价温和；危机里资金约束收紧（<a href="/econ/funding-constraints-capm">资金约束与 CAPM 偏离</a>），中介被迫减仓，市场流动性骤降，价格向受约束的边际者坍缩——<a href="/econ/intermediary-asset-pricing">中介资产定价</a>与<a href="/econ/leverage-cycle">杠杆周期</a>把这写成螺旋。所以流动性溢价的时变性远大于其均值：静态的价差—收益回归在危机年份系统性失灵，漏掉的不是常数项而是状态项。这也接得上第一课的 HJB：流动性是状态变量，对冲需求与流动性溢价是同一枚硬币的两面。</p><p>第一张图把摩擦分成两通道；这一张把「螺旋」两个字拆开——危机中资金约束与市场流动性如何互相喂给、逐圈放大，这正是溢价时变性的来源。</p>',3)),(e(),i(r,null,{default:a(()=>[t(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E8%B4%9F%E9%9D%A2%E5%86%B2%E5%87%BB%EF%BC%9A%E4%BA%8F%E6%8D%9F%E6%88%96%E8%9E%8D%E8%B5%84%E6%9D%A1%E4%BB%B6%E6%94%B6%E7%B4%A7%22%5D%20--%3E%20MARGIN%5B%22%E8%B5%84%E9%87%91%E7%BA%A6%E6%9D%9F%E6%94%B6%E7%B4%A7%E3%80%81%E4%BF%9D%E8%AF%81%E9%87%91%E4%B8%8A%E8%B0%83%22%5D%0A%20%20MARGIN%20--%3E%20SELL%5B%22%E4%B8%AD%E4%BB%8B%E8%A2%AB%E8%BF%AB%E5%87%8F%E4%BB%93%22%5D%0A%20%20SELL%20--%3E%20DROP%5B%22%E4%BB%B7%E6%A0%BC%E4%B8%8B%E8%B7%8C%E3%80%81%E4%B9%B0%E5%8D%96%E4%BB%B7%E5%B7%AE%E5%8F%98%E5%AE%BD%22%5D%0A%20%20DROP%20--%3E%20COLL%5B%22%E6%8A%B5%E6%8A%BC%E5%93%81%E4%BB%B7%E5%80%BC%E7%BC%A9%E6%B0%B4%E3%80%81%E8%9E%8D%E8%B5%84%E6%9B%B4%E9%9A%BE%22%5D%0A%20%20COLL%20--%3E%20MARGIN%0A%20%20DROP%20--%3E%20LIQ%5B%22%E5%B8%82%E5%9C%BA%E6%B5%81%E5%8A%A8%E6%80%A7%E9%AA%A4%E9%99%8D%22%5D%0A%20%20LIQ%20--%3E%20PREM%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E6%BA%A2%E4%BB%B7%E9%A3%99%E5%8D%87%EF%BC%8C%E5%8F%AA%E5%89%A9%E8%83%BD%E5%87%BA%E6%89%8B%E7%9A%84%E4%BA%BA%E6%8E%A5%E7%9B%98%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">LCAPM 的四个贝塔可以翻译成四份保单：大盘跌你也跌（市场贝塔）；市场流动性变坏你也变坏（流动性水平贝塔）；你自己变得更难卖恰逢大盘下跌（收益与流动性的交叉贝塔）；你变得更难卖恰逢市场普遍难卖（流动性对流动性的贝塔）。每份保单风险不同、保费各付各的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>度量内生：价差与波动同涨同跌，「流动性溢价」里混着波动风险的份额，四个贝塔在线性近似里也拆不干净。螺旋是非线性的，线性贝塔是它的局部切片，样本又多来自平稳期，危机中的估值得靠极值样本、误差极大。水平与风险两层不要互相冒充：价差补偿不是超额收益，流动性贝塔也不是价差；清算折价的实证口径（禁售、锁仓、限售股）各自混着别的摩擦，引用时先看对照设计。</p><p><span class="marginnote">常见误区：把「流动性溢价」当成一个永远为正的常数补贴。常态下它温和、还能被低频调仓摊薄；只有危机中资金螺旋转起来它才飙升。用平稳年份估出的平均溢价去外推危机期，会同时看错水平和状态——静态回归漏掉的是状态项，不是噪声项。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>交易摩擦分两笔记账：持有补偿的水平效应，与流动性共同冲击的风险效应。</li><li>LCAPM 把预期超额收益写成四个贝塔的加权和；流动性由此从「特征」升格为「状态变量」。</li><li>资金约束是时变性的来源：常态温和、危机放大，静态回归漏掉的是状态项。</li><li>水平效应受摊薄限制，三成是「完全不可交易」的上限而非典型值。</li><li>出处：Amihud and Mendelson 1986；Amihud, <em>JFE</em> 2002；Pastor and Stambaugh, <em>JPE</em> 2003；Acharya and Pedersen, <em>JFE</em> 2005；Brunnermeier and Pedersen, <em>RFS</em> 2009。</li></ul>',6))])}const C=o(l,[["render",p]]);export{_ as __pageData,C as default};
